<?php

/* Direct/nested operations exercise ordering, conversions, sharing and failure without native slots. */
return [
	'write_path_cross_family_guards' => ['function mixedpath(mixed &$m): void { $m["child"]["new"] = 1; } function dynamicpath(dynamic &$d): void { $d["child"]["new"] = 1; } $m mixed = {child: {}}; $d dynamic = {child: {}};',
		'([&]() { auto mixed_child = (*local_m.shared_table_if())->at(scpp::string_t{"child"}); auto dynamic_child = local_d->at(scpp::string_t{"child"}); (*local_m.shared_table_if())->set(scpp::string_t{"child"}, dynamic_child); local_d->set(scpp::string_t{"child"}, mixed_child); int caught = 0; try { function_mixedpath(local_m); } catch (const std::exception&) { ++caught; } try { function_dynamicpath(local_d); } catch (const std::exception&) { ++caught; } return caught == 2 && dynamic_child.dynamic_if()->get()->size() == 0 && (*mixed_child.shared_table_if())->size() == 0; }())'],
	'write_path_cross_family_values' => ['function mixedvalue(mixed &$m, mixed $v): void { $m["child"]["new"] = $v; } function dynamicvalue(dynamic &$d, mixed $v): void { $d["child"]["new"] = $v; } $m mixed = null; $table mixed = {}; $d dynamic = {child: {}};',
		'([&]() { auto child = local_d->at(scpp::string_t{"child"}); int caught = 0; try { function_mixedvalue(local_m, child); } catch (const std::exception&) { ++caught; } try { function_dynamicvalue(local_d, local_table); } catch (const std::exception&) { ++caught; } return caught == 2 && local_m.is_null().native_value() && child.dynamic_if()->get()->size() == 0; }())'],
	'write_path_typed' => ['$rows vector<hash<vector<int>>> = [{staff: [1]}]; $rows[0]["staff"][] = 2; $x = $rows[0]["staff"][0] = 7; $a = $rows[0]["staff"][0]; $b = $rows[0]["staff"][1];',
		'local_x.native_value() == 7 && local_a.native_value() == 7 && local_b.native_value() == 2'],
	'write_path_mixed' => ['$a mixed = null; $a["child"]["items"][] = 3; $b = $a; $a["child"]["items"][0] = 9; $x int = $a["child"]["items"][0]; $y int = $b["child"]["items"][0];',
		'local_x.native_value() == 9 && local_y.native_value() == 3'],
	'write_path_dynamic' => ['$d dynamic = {child: {items: [1]}}; $alias = $d; $child = $d["child"]; $d["child"]["items"][] = 2; $d["child"]["items"][0] = 7; $x int = $alias["child"]["items"][0]; $y int = $child["items"][1];',
