	'write_path_literal_context' => ['$m mixed = {}; $m["child"]["leaf"] = {n: 3}; $d dynamic = {child: {}}; $d["child"]["leaf"] = {n: 4}; $d["child"]["leaf"]["n"] = 5; $x int = $m["child"]["leaf"]["n"]; $y int = $d["child"]["leaf"]["n"];',
