	'write_path_order' => ['function key(int &$n, int $tag): int { $n = $n * 10 + $tag; return 0; } function value(int &$n): int { $n = $n * 10 + 3; return 8; } $n = 0; $v vector<vector<int>> = [[1]]; $v[key($n, 1)][key($n, 2)] = value($n);',
