		'local_x.native_value() == 1 && local_y.native_value() == 9 && local_old.get() != local_d.get()'],
	'write_path_invalid_key' => ['function store(mixed &$m, mixed $key, int &$n): void { $m["new"][$key] = $n++; }',
		'([&]() { scpp::mixed_t m{scpp::null}; scpp::int_t<> n{0LL}; bool caught = false; try { function_store(m, scpp::mixed_t{true}, n); } catch (const std::exception&) { caught = true; } return caught && m.is_null().native_value() && n.native_value() == 0; }())'],
	'write_path_rhs_failure' => ['function store(mixed &$m): void { $m["new"]["leaf"] = {a: 1, a: 2}; } function typed(hash<vector<int>> &$h, mixed $value): void { $h["new"][] = $value; }',
