	'write_nested_literals' => ['$rows vector<vector<int>> = []; $rows[] = [1, 2]; $d dynamic = {}; $d["child"] = {n: 3}; $m mixed = {}; $m["child"] = {n: 4}; $x = $rows[0][1];',
